// Scan throughput index — record JAH-GPCS-DOCSCANNER-000001
// Property of Justin Addam Higgins (JAH). Deterministic: same inputs, same output.
var m = {"dpi": 600, "ppm": 40};
var value = (m.dpi/100*m.ppm);
if (!isFinite(value)) { console.log('DEMO_FAIL|JAH-GPCS-DOCSCANNER-000001|non-finite'); process.exit(1); }
console.log('DEMO_OK|JAH-GPCS-DOCSCANNER-000001|' + value.toFixed(2) + ' throughput index');

